// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address account, address operator, address otherOperator) public {
        vm.assume(account != address(0) && operator != address(0) && otherOperator != address(0));
        vm.assume(operator != otherOperator);

        // Set approval for operator
        vm.prank(account);
        c.setApprovalForAll(operator, true);

        // The rule: isApprovedForAll should return true for the approved operator, false for a different operator
        bool approvedResult = c.isApprovedForAll(account, operator);
        bool notApprovedResult = c.isApprovedForAll(account, otherOperator);

        assertTrue(approvedResult && !notApprovedResult, "isApprovedForAll should return true for approved operator and false for non-approved");
    }
}

